<script setup lang="ts">import type{Company,CompanyStatus}from'../types';import{fitScore,timingFor,visaFit}from'../services/recommendations';import{setCompanyStatus,state}from'../stores/career';defineProps<{company:Company}>();const statuses:CompanyStatus[]=['未开始','研究中','已投递','面试中','暂停'];</script>
<template><article class="card company-card"><header><div><h3>{{company.name}}</h3><p>{{company.industry}} · {{company.cities.join(' / ')}}</p></div><span class="pill priority">{{company.priority}}</span></header><div class="meter"><i :style="{width:fitScore(company)+'%'}"/></div><small>个人匹配度 {{fitScore(company)}}/100</small><p><b>推荐原因：</b>{{company.fitReason}}</p><div class="tags"><span v-for="role in company.recommendedRoles" :key="role" class="pill">{{role}}</span></div><div class="meta"><span class="pill">{{visaFit(company)[0]}}</span><span>{{timingFor(company)[0]}}</span></div><select class="status-select" :value="state.statuses[company.name]||'未开始'" @change="setCompanyStatus(company.name,($event.target as HTMLSelectElement).value as CompanyStatus)"><option v-for="s in statuses">{{s}}</option></select><footer><RouterLink class="button primary" :to="`/companies/${company.id}`">查看档案</RouterLink><a class="button" :href="company.careerUrl" target="_blank" rel="noopener">公司招聘主页 ↗</a></footer></article></template>
